#!/usr/bin/env python3
"""Native generated bytes/base64 process checks, no external effects."""
import base64
import json
import subprocess
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CRATE = ROOT / "fixtures/native-bytes"
with (CRATE / "Cargo.toml").open("rb") as f:
    name = tomllib.load(f)["package"]["name"]
BINARY = CRATE / "target/debug" / name


def run(data):
    return subprocess.run([str(BINARY)], input=json.dumps({
        "protocol_version": 2, "input": data,
    }), capture_output=True, text=True, timeout=20)


sample = {"message": "Hello 🙂", "ascii": "ASCII text",
          "charset": "us-ascii", "data": {"items": [2, True]}}
first = run(sample)
assert first.returncode == 0, (first.stdout, first.stderr)
result = json.loads(first.stdout)
assert result == {"protocol_version": 2, "status": "completed", "result": {
    "base64": "SGVsbG8g8J+Zgg==",
    "unpadded": "SGVsbG8g8J+Zgg",
    "roundtrip": "Hello 🙂",
    "ascii": "ASCII text",
    "jsonBase64": base64.b64encode(b'{"items":[2,true]}').decode("ascii"),
}}, result
assert run(sample).stdout == first.stdout, "byte conversion should be deterministic"

for bad in (
    dict(sample, charset="ISO-8859-2"),
    dict(sample, ascii="Å"),
    dict(sample, ascii=42),
    dict(sample, message=None),
):
    response = run(bad)
    assert response.returncode != 0 or json.loads(response.stdout).get("status") == "failed", (
        "invalid input must fail", bad, response.stdout, response.stderr
    )

print("NATIVE_BYTES_PROCESS_PASS: UTF-8, ASCII, Base64 padding, JSON, types, replay")
